	/**
	 * Default Constructor
	 */
    public AccountService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new AccountEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(AccountRepository.class) );
		this.validator		= applicationContext.getBean(AccountValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Account
	 */
		public Account createAccount( CreateAccountCommand command ) {

		Account entity = new Account();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setAccountId( command.getAccountId() );
            entity.setAccountNumber( command.getAccountNumber() );
            entity.setIban( command.getIban() );
            entity.setBic( command.getBic() );
            entity.setOpenedDate( command.getOpenedDate() );
            entity.setCurrency( command.getCurrency() );
            entity.setBalance( command.getBalance() );
            entity.setAvailableBalance( command.getAvailableBalance() );
            entity.setAccountType( command.getAccountType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Account {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateAccountCommand
	 * @return		Account
	 */
	public Account updateAccount( UpdateAccountCommand command ) {

		Account entity = new Account();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setAccountId( command.getAccountId() );
            entity.setAccountNumber( command.getAccountNumber() );
            entity.setIban( command.getIban() );
            entity.setBic( command.getBic() );
            entity.setOpenedDate( command.getOpenedDate() );
            entity.setCurrency( command.getCurrency() );
            entity.setBalance( command.getBalance() );
            entity.setAvailableBalance( command.getAvailableBalance() );
            entity.setCustomer( command.getCustomer() );
            entity.setInstitution( command.getInstitution() );
            entity.setTransactions( command.getTransactions() );
            entity.setCards( command.getCards() );
            entity.setStatements( command.getStatements() );
            entity.setMandates( command.getMandates() );
            entity.setAccountType( command.getAccountType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Account {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteAccountCommand
	 */
	public void delete( DeleteAccountCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getAccountId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Account {0} ", id );

	}

	/**
	 * Method to retrieve the Account via AccountFetchOneSummary
	 * @param 	summary AccountFetchOneSummary
	 * @return 	AccountFetchOneResponse
	 */
	public Account getAccount( AccountFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "AccountFetchOneSummary arg cannot be null" );

		Account entity = null;
		UUID id = summary.getAccountId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Account using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Accounts
	 *
	 * @return 	List<Account>
	 */
    public List<Account> getAllAccount() {
		List<Account> list = projector.findAll( new FindAllAccountQuery() );
		return list;
	}

	/**
	 * assign Customer on Account
	 * @param		command AssignCustomerToAccountCommand
	 */
	public void assignCustomer( AssignCustomerToAccountCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getAccountId(), command.getAssignment());

	}

